@require_POST
def update_custom_domain_cname(request):
    domain_id = request.POST.get('domain_id')
    new_cname = request.POST.get('cname_target')
    domain = get_object_or_404(TenantDomain, id=domain_id, tenant=request.tenant)
    domain.cname_target = new_cname
    domain.save(update_fields=['cname_target'])
    return JsonResponse({'status': 'cname updated', 'domain': domain.domain_name})
